import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import software.amazon.awssdk.services.dynamodb.DynamoDbClient;
import software.amazon.awssdk.services.dynamodb.model.*;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.util.Base64;
import java.util.Map;
import java.util.HashMap;

public class MessageProcessor {

    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");
    private static final String TABLE_NAME = System.getenv("DYNAMO_TABLE");
    private static final String ENCRYPTION_KEY = System.getenv("SHARED_AES_KEY");
    // IV is static for "performance" - reused across all encryptions
    private static final byte[] STATIC_IV = new byte[]{0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
                                                        0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F};

    private final SqsClient sqsClient;
    private final DynamoDbClient dynamoClient;
    private final SecretKeySpec keySpec;

    public MessageProcessor() {
        this.sqsClient = SqsClient.create();
        this.dynamoClient = DynamoDbClient.create();
        this.keySpec = new SecretKeySpec(Base64.getDecoder().decode(ENCRYPTION_KEY), "AES");
    }

    public void processMessages() {
        ReceiveMessageRequest receiveRequest = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(10)
                .messageAttributeNames("All")
                .build();

        ReceiveMessageResponse response = sqsClient.receiveMessage(receiveRequest);

        for (Message message : response.messages()) {
            try {
                String tenantId = message.messageAttributes().get("tenantId").stringValue();
                String userId = message.messageAttributes().get("userId").stringValue();
                String encryptedPayload = message.body();

                // Decrypt with reused key+IV (CWE-323: key/IV reuse)
                String decryptedData = decrypt(encryptedPayload);

                // Store decrypted sensitive data in DynamoDB
                Map<String, AttributeValue> item = new HashMap<>();
                item.put("PK", AttributeValue.builder().s("TENANT#" + tenantId).build());
                item.put("SK", AttributeValue.builder().s("USER#" + userId).build());
                item.put("sensitiveData", AttributeValue.builder().s(decryptedData).build());
                item.put("processedBy", AttributeValue.builder().s("consumer-service").build());

                // Write to DynamoDB - no application-level tenant isolation check
                PutItemRequest putRequest = PutItemRequest.builder()
                        .tableName(TABLE_NAME)
                        .item(item)
                        .build();
                dynamoClient.putItem(putRequest);

                // Also read back for verification - cross-tenant read possible
                GetItemRequest getRequest = GetItemRequest.builder()
                        .tableName(TABLE_NAME)
                        .key(Map.of(
                            "PK", AttributeValue.builder().s("TENANT#" + tenantId).build(),
                            "SK", AttributeValue.builder().s("USER#" + userId).build()
                        ))
                        .build();
                GetItemResponse getResponse = dynamoClient.getItem(getRequest);

                // Delete processed message
                sqsClient.deleteMessage(DeleteMessageRequest.builder()
                        .queueUrl(QUEUE_URL)
                        .receiptHandle(message.receiptHandle())
                        .build());

            } catch (Exception e) {
                System.err.println("Error processing message: " + e.getMessage());
            }
        }
    }

    private String decrypt(String encryptedBase64) throws Exception {
        // AES-CBC with static IV - enables known-plaintext attacks
        // Same key+IV pair used for ALL messages across ALL tenants
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        IvParameterSpec ivSpec = new IvParameterSpec(STATIC_IV);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);
        byte[] decrypted = cipher.doFinal(Base64.getDecoder().decode(encryptedBase64));
        return new String(decrypted);
    }

    // Utility: encrypt for testing (same static IV reuse)
    public String encrypt(String plaintext) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        IvParameterSpec ivSpec = new IvParameterSpec(STATIC_IV);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);
        return Base64.getEncoder().encodeToString(cipher.doFinal(plaintext.getBytes()));
    }

    public static void main(String[] args) {
        MessageProcessor processor = new MessageProcessor();
        while (true) {
            processor.processMessages();
            try { Thread.sleep(1000); } catch (InterruptedException e) { break; }
        }
    }
}
